export function cappedRunningTotal(nums, cap) {
    let total = 0;
    let result = [];
    let capped = false;

    for (let num of nums) {
        if (capped) {
            result.push(cap);
        } else {
            total += num;
            if (total > cap) {
                result.push(cap);
                capped = true;
            } else {
                result.push(total);
            }
        }
    }

    return result;
}
